import { defineIndicator } from '../../registry';
import { COLOR } from '../common';
import { PERIOD_INPUT, ROW, requireSeries, trailingTwelveMonths, valueAt } from './common';

/** Cash generated by operations per fiscal period, plus the trailing twelve months. */
export const OPERATING_CASH_FLOW = defineIndicator({
  id: 'fin-ocf',
  name: 'Operating Cash Flow',
  shortName: 'OCF',
  category: 'financials',
  keywords: ['operating cash flow', 'cash flow', 'ocf', 'cash from operations', 'financials'],
  overlay: false,
  format: 'volume',
  usesFundamentals: true,
  inputs: {
    period: PERIOD_INPUT,
    ttm: { kind: 'bool', label: 'TTM', default: true, hideInTitle: true },
  },
  outputs: [
    { type: 'plot', id: 'ocf', title: 'Operating Cash Flow', kind: 'step', color: COLOR.blue },
    { type: 'plot', id: 'ttm', title: 'TTM', kind: 'step', color: COLOR.orange },
  ],
  setup({ inputs, env }) {
    const ocf = requireSeries(env.fundamentals, inputs.period, 'cashflow', ROW.ocf, 'operating cash flow');
    const ttm = trailingTwelveMonths(ocf, inputs.period);
    return (c) => {
      c.set('ocf', valueAt(ocf, c.time[c.i]!));
      if (inputs.ttm) c.set('ttm', valueAt(ttm, c.time[c.i]!));
    };
  },
});
